using System;using System.Data;using System.Drawing;using System.Windows.Forms;
namespace AshkanHotelManager{public partial class NotificationCenterForm:Form{DataGridView grid;public NotificationCenterForm(){InitializeComponent();Text=App.T("notifications");BackColor=Ui.Bg;Build();App.ApplyDirection(this);}void Build(){var head=new Panel{Dock=DockStyle.Top,Height=92,BackColor=Ui.Navy,Padding=new Padding(24)};head.Controls.Add(new Label{Text=App.T("notifications"),Dock=DockStyle.Top,Height=38,ForeColor=Color.White,Font=Ui.Font(22,FontStyle.Bold),TextAlign=App.Persian?ContentAlignment.MiddleRight:ContentAlignment.MiddleLeft});head.Controls.Add(new Label{Text=App.Persian?"هشدارهای عملیاتی و موارد نیازمند توجه":"Operational alerts and items needing attention",Dock=DockStyle.Bottom,Height=28,ForeColor=Color.FromArgb(203,213,225),Font=Ui.Font(9.5f),TextAlign=App.Persian?ContentAlignment.MiddleRight:ContentAlignment.MiddleLeft});Controls.Add(head);grid=new DataGridView{Dock=DockStyle.Fill};Ui.Grid(grid);grid.DataSource=BuildData();grid.CellFormatting+=(s,e)=>Ui.FormatStatusCell(grid,e);Controls.Add(grid);grid.BringToFront();head.BringToFront();}DataTable BuildData(){var t=new DataTable();t.Columns.Add(App.Persian?"نوع":"Type");t.Columns.Add(App.Persian?"پیام":"Message");t.Columns.Add(App.Persian?"اولویت":"Priority");int dirty=DataStore.Db.Tables["Rooms"].Select("Status = 'Cleaning'").Length,maint=DataStore.Db.Tables["Rooms"].Select("Status = 'Maintenance'").Length;var today=DateTime.Today.ToString("yyyy-MM-dd");int arr=0,dep=0;foreach(DataRow r in DataStore.Db.Tables["Reservations"].Rows){DateTime d;if(DateTime.TryParse(Convert.ToString(r["CheckIn"]),out d)&&d.Date==DateTime.Today)arr++;if(DateTime.TryParse(Convert.ToString(r["CheckOut"]),out d)&&d.Date==DateTime.Today)dep++;}if(arr>0)t.Rows.Add(App.Persian?"پذیرش":"Front desk",String.Format(App.Persian?"{0} ورود برای امروز ثبت شده است.":"{0} arrivals are scheduled today.",arr),"Info");if(dep>0)t.Rows.Add(App.Persian?"پذیرش":"Front desk",String.Format(App.Persian?"{0} خروج برای امروز ثبت شده است.":"{0} departures are scheduled today.",dep),"Info");if(dirty>0)t.Rows.Add(App.Persian?"خانه‌داری":"Housekeeping",String.Format(App.Persian?"{0} اتاق منتظر نظافت است.":"{0} rooms are waiting for cleaning.",dirty),"High");if(maint>0)t.Rows.Add(App.Persian?"تعمیرات":"Maintenance",String.Format(App.Persian?"{0} اتاق در تعمیرات است.":"{0} rooms are under maintenance.",maint),"Urgent");if(t.Rows.Count==0)t.Rows.Add(App.Persian?"سیستم":"System",App.T("allClear"),"Normal");return t;}}}
